using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
public partial class KeyframeEditorOperations
{
    private static Control NewCurve()=>GD.Load<GDScript>("res://Workspaces/SceneWorkspace/scripts/Timeline/actor_value_curve.gd").New().As<Control>();
    private static Godot.Range NewNumber()=>new DragNumber();
    public void add_state_value(Control owner,Resource track,Resource key)
    {
        var actor=Actor(owner);if(actor==null)return;var asset=Asset(actor);var document=asset["document"].As<Resource>();var path=track.Get("path").AsStringArray();var item=document?.Call("component",path[1]).As<Resource>();var choose=new OptionButton{Name="KeyframeTransformationState",CustomMinimumSize=new Vector2(150,0),FitToLongestItem=false,TooltipText="State to morph into at this keyframe"};Details(owner).AddChild(choose);if(item==null){choose.AddItem("Missing component");choose.Disabled=true;return;}foreach(var entry in item.Get("states").AsGodotArray()){var state=entry.As<Resource>();choose.AddItem(state.Get("title").AsString());choose.SetItemMetadata(choose.ItemCount-1,state.Get("id"));}string id=key.Get("id").AsString();void Update(){var current=_timeline.keyframe_for_id(actor,id);if(current==null)return;for(int i=0;i<choose.ItemCount;i++)if(choose.GetItemMetadata(i).ToString()==current.Get("value").ToString()){choose.Select(i);break;}}Update();Updaters(owner).Add(Callable.From(Update));choose.ItemSelected+=index=>change_keys(owner,id,new Settings{["value"]=choose.GetItemMetadata((int)index).ToString()},false,-1);
    }
    public void add_curve_button(Control owner,Resource key)
    {
        var button=new Button{Text="Value curve",Alignment=HorizontalAlignment.Left,CustomMinimumSize=new Vector2(158,0),TooltipText="Edit easing from this keyframe to the next keyframe on this track"};Details(owner).AddChild(button);var preview=NewCurve();preview.MouseFilter=Control.MouseFilterEnum.Ignore;button.AddChild(preview);preview.Position=new Vector2(90,2);preview.Size=new Vector2(62,22);string id=key.Get("id").AsString();void Update(){var actor=Actor(owner);var current=actor!=null?_timeline.keyframe_for_id(actor,id):null;if(current==null)return;preview.Set("curve",_curves.for_key(current));preview.Set("stepped",current.Get("interpolation").AsInt32()==2);preview.QueueRedraw();}Update();Updaters(owner).Add(Callable.From(Update));button.Pressed+=()=>open_curve_menu(owner,id);
    }
    public void open_curve_menu(Control owner,string id)
    {
        var old=owner.Get("curve_popup").As<PopupPanel>();if(GodotObject.IsInstanceValid(old))old!.QueueFree();var actor=Actor(owner);var key=actor!=null?_timeline.keyframe_for_id(actor,id):null;if(key==null)return;var popup=new PopupPanel();owner.Set("curve_popup",popup);owner.AddChild(popup);var content=new VBoxContainer();popup.AddChild(content);content.AddChild(new Label{Text="VALUE CURVE  ·  easing to the next key"});var graph=NewCurve();graph.Set("editable",true);graph.CustomMinimumSize=new Vector2(420,230);graph.Set("curve",_curves.for_key(key));graph.Set("stepped",key.Get("interpolation").AsInt32()==2);content.AddChild(graph);graph.Connect("edit_started",Callable.From(()=>begin_edit(owner)));graph.Connect("preview_changed",Callable.From<Curve>(curve=>change_keys(owner,id,new Settings{["value_curve"]=curve},true,-1)));graph.Connect("edit_committed",Callable.From(()=>finish_edit(owner)));graph.Connect("edit_cancelled",Callable.From(()=>cancel_edit(owner)));popup.PopupHide+=()=>_curves.cancel_edit(graph);
        var model=Model(owner);var syncCurve=Callable.From(()=>{if(owner.Get("_editing").AsBool()||!GodotObject.IsInstanceValid(graph))return;var current=_timeline.keyframe_for_id(actor!,id);if(current==null)return;graph.Set("curve",_curves.for_key(current));graph.Set("stepped",current.Get("interpolation").AsInt32()==2);graph.QueueRedraw();});model.Connect("changed",syncCurve);popup.TreeExiting+=()=>{if(GodotObject.IsInstanceValid(model)&&model.IsConnected("changed",syncCurve))model.Disconnect("changed",syncCurve);};
        var presets=new HFlowContainer();content.AddChild(presets);var row=new HBoxContainer();content.AddChild(row);var reset=new Button{Text="↺  Reset selected point's tangents",TooltipText="Reset both tangents of the selected point to straight segments"};reset.AddThemeColorOverride("font_color",new Color("ffce80"));row.AddChild(reset);reset.Pressed+=()=>_curves.reset_tangents(graph);var parameterRow=new HBoxContainer();content.AddChild(parameterRow);var label=new Label();parameterRow.AddChild(label);var parameter=NewNumber();parameter.CustomMinimumSize=new Vector2(100,0);parameterRow.AddChild(parameter);string setting=key.Get("curve_template").AsString();
        void Configure(string name,double amount){setting=name;parameterRow.Visible=name is "Ease" or "Smoothstep" or "Sin wave" or "Step";label.Text=name=="Sin wave"?"Frequency":name=="Step"?"Steps":"Adjustment";parameter.Step=name=="Step"?1:.01;parameter.MinValue=name=="Ease"?-10:name=="Step"?1:name=="Sin wave"?.1:0;parameter.MaxValue=name=="Ease"?10:name=="Step"?64:name=="Sin wave"?16:1;parameter.AllowLesser=name=="Ease";parameter.AllowGreater=name=="Ease";parameter.SetValueNoSignal(amount);}
        void Apply(double amount,bool preview){var curve=_curves.template(setting,amount);graph.Set("curve",curve);graph.Set("stepped",false);change_keys(owner,id,new Settings{["value_curve"]=curve,["curve_template"]=setting,["curve_adjustment"]=amount},preview,-1);graph.QueueRedraw();}
        Configure(setting,key.Get("curve_adjustment").AsDouble());parameter.Connect("interaction_started",Callable.From(()=>begin_edit(owner)));parameter.Connect("preview_changed",Callable.From<double>(amount=>Apply(amount,true)));parameter.Connect("drag_committed",Callable.From<double>(_=>finish_edit(owner)));parameter.Connect("drag_cancelled",Callable.From(()=>cancel_edit(owner)));parameter.ValueChanged+=amount=>Apply(amount,false);var syncParameter=Callable.From(()=>{if(owner.Get("_editing").AsBool())return;var current=_timeline.keyframe_for_id(actor!,id);if(current!=null)Configure(current.Get("curve_template").AsString(),current.Get("curve_adjustment").AsDouble());});model.Connect("changed",syncParameter);popup.TreeExiting+=()=>{if(GodotObject.IsInstanceValid(model)&&model.IsConnected("changed",syncParameter))model.Disconnect("changed",syncParameter);};foreach(string name in new[]{"Linear","Ease","Smoothstep","Sin wave","Step"}){var choice=new Button{Text=name};presets.AddChild(choice);choice.Pressed+=()=>{double amount=name=="Linear"?0:name=="Step"?4:1;Configure(name,amount);Apply(amount,false);};}var help=new Label{Text="Select a point · Drag gold handles to bend the curve\nClick adds points · Right-click removes points · Esc cancels drag"};help.AddThemeFontSizeOverride("font_size",10);content.AddChild(help);popup.PopupCentered();
    }
}

